pub async fn verify_quorum(&self, proposal_id: &TxId) -> Result<CommitProof, ConsensusError> {
    let votes = self.vote_accumulator.get_votes(proposal_id).await?;
    if votes.len() >= self.threshold_2f_plus_1() {
        Ok(self.build_proof(proposal_id, votes)?)
    } else {
        Err(ConsensusError::QuorumPending)
    }
}

